// ============================================================================
// Config & Safety Gate
// Env-only configuration, fail-safe flags, fiscal-quarter and as-of resolution,
// webhook authentication, and notification-destination validation.
//   * Safe-ON  (SANDBOX_MODE, DRY_RUN) turn OFF only on false/0/no/off.
//   * Safe-OFF (NOTIFICATIONS_ENABLED, HUBSPOT_MUTATIONS_ENABLED, ...) turn ON
//     only on true/1/yes/on. Typos keep the safe value. Blocked $env => safe.
// Webhook URLs are secrets: only "is set / host allowed" booleans and the
// host name leave this node; the URL itself is read again inside the HTTP node.
// ============================================================================
const TRUTHY = ['true', '1', 'yes', 'on'];
const FALSY = ['false', '0', 'no', 'off'];
let envBlocked = false;
function readEnv(key) {
  try {
    const v = $env[key];
    return v === undefined || v === null ? '' : String(v).trim();
  } catch (e) {
    envBlocked = true;
    return '';
  }
}
const str = (k, d = '') => readEnv(k) || d;
const safeOn = (k) => !FALSY.includes(readEnv(k).toLowerCase());
const safeOff = (k) => TRUTHY.includes(readEnv(k).toLowerCase());
const list = (k, d = '') => (readEnv(k) || d).split(',').map((s) => s.trim()).filter(Boolean);
const prop = (k, d) => (readEnv(k) || d).replace(/[^a-z0-9_]/gi, '');
const configErrors = [];
const warnings = [];
const DEC = /^\d+(\.\d+)?$/;
const intIn = (k, d, min, max) => {
  const raw = readEnv(k);
  if (raw === '') return d;
  const n = Number(raw);
  if (!Number.isInteger(n) || n < min || n > max) { configErrors.push(`${k} must be an integer ${min}-${max} (got "${raw}")`); return d; }
  return n;
};
const decIn = (k, d, max) => {
  const raw = readEnv(k).replace(/[,_\s]/g, '');
  if (raw === '') return d;
  if (!DEC.test(raw) || (max !== undefined && Number(raw) > max)) { configErrors.push(`${k} must be a decimal${max !== undefined ? ' <= ' + max : ''} (got "${readEnv(k)}")`); return d; }
  return raw;
};
const DAY = 86400000;
const parseYmd = (s) => {
  const m = String(s || '').match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const ms = Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  return new Date(ms).toISOString().slice(0, 10) === m[0] ? ms : null; // rejects 2026-13-01, 2026-02-30
};

const sandboxMode = safeOn('SANDBOX_MODE');
const dryRun = safeOn('DRY_RUN');
const notificationsEnabled = safeOff('NOTIFICATIONS_ENABLED');
const hubspotMutationsEnabled = safeOff('HUBSPOT_MUTATIONS_ENABLED');
const hasHubspotToken = readEnv('HUBSPOT_ACCESS_TOKEN') !== '';
const hasWebhookSecret = readEnv('WEBHOOK_SHARED_SECRET').length >= 16;

const SYNTHETIC_PORTAL_ID = '99000001';
const configuredPortalId = str('HUBSPOT_PORTAL_ID');
if (!sandboxMode) {
  const problems = [];
  if (!hasHubspotToken) problems.push('HUBSPOT_ACCESS_TOKEN is not set');
  if (!/^\d{1,12}$/.test(configuredPortalId)) problems.push('HUBSPOT_PORTAL_ID must be a numeric HubSpot portal ID');
  if (problems.length) throw new Error('Live mode (SANDBOX_MODE=false) refused: ' + problems.join('; ') + '. Fix the variables or keep SANDBOX_MODE=true.');
}

// ---- Trigger & webhook auth ---------------------------------------------------
function constantTimeEqual(a, b) {
  const x = String(a || ''), y = String(b || '');
  const len = Math.max(x.length, y.length);
  let diff = x.length ^ y.length;
  for (let i = 0; i < len; i++) diff |= (x.charCodeAt(i) || 0) ^ (y.charCodeAt(i) || 0);
  return diff === 0 && x.length > 0;
}
const raw = $input.first().json || {};
const isWebhook = raw && typeof raw === 'object' && 'body' in raw && 'headers' in raw;
let requested = {};
if (isWebhook) {
  const headers = Object.fromEntries(Object.entries(raw.headers || {}).map(([k, v]) => [String(k).toLowerCase(), v]));
  const query = raw.query && typeof raw.query === 'object' ? raw.query : {};
  const provided = headers['x-forecast-secret'] !== undefined ? headers['x-forecast-secret'] : query.forecast_secret;
  if (!sandboxMode && !(hasWebhookSecret && constantTimeEqual(provided, readEnv('WEBHOOK_SHARED_SECRET')))) {
    throw new Error('Webhook rejected: WEBHOOK_SHARED_SECRET (16+ chars) must be set and sent as header x-forecast-secret (or ?forecast_secret=).');
  }
  const b = raw.body && typeof raw.body === 'object' ? raw.body : {};
  requested = { quarterStart: b.quarter_start ? String(b.quarter_start).trim() : '', asOf: b.as_of ? String(b.as_of).trim() : '' };
}

// ---- As-of date & fiscal quarter (UTC) -----------------------------------------
const nowMs = (() => {
  const o = str('NOW_OVERRIDE');
  return o && !Number.isNaN(Date.parse(o)) ? Date.parse(o) : Date.now();
})();
const asOfRaw = requested.asOf || str('AS_OF_DATE');
let asOfMs = asOfRaw ? parseYmd(asOfRaw) : Math.floor(nowMs / DAY) * DAY;
if (asOfMs === null) throw new Error(`Invalid as-of date "${asOfRaw}"; expected YYYY-MM-DD.`);
if (asOfMs > Math.floor(nowMs / DAY) * DAY) throw new Error(`As-of date ${asOfRaw} is in the future.`);

const fyStartMonth = intIn('FISCAL_YEAR_START_MONTH', 1, 1, 12);
const qsRaw = requested.quarterStart || str('QUARTER_START_DATE');
let qStartMs;
if (qsRaw) {
  qStartMs = parseYmd(qsRaw);
  if (qStartMs === null) throw new Error(`Invalid quarter start "${qsRaw}"; expected YYYY-MM-DD.`);
  const d = new Date(qStartMs);
  if (d.getUTCDate() !== 1 || (d.getUTCMonth() + 1 - fyStartMonth + 12) % 3 !== 0) {
    throw new Error(`Quarter start ${qsRaw} is not the first day of a fiscal quarter (FISCAL_YEAR_START_MONTH=${fyStartMonth}).`);
  }
} else {
  const a = new Date(asOfMs);
  const monthsIntoFy = (a.getUTCMonth() + 1 - fyStartMonth + 12) % 12;
  qStartMs = Date.UTC(a.getUTCFullYear(), a.getUTCMonth() - (monthsIntoFy % 3), 1);
}
const qs = new Date(qStartMs);
const qEndMs = Date.UTC(qs.getUTCFullYear(), qs.getUTCMonth() + 3, 1);
const monthsIntoFy = (qs.getUTCMonth() + 1 - fyStartMonth + 12) % 12;
const quarterNumber = Math.floor(monthsIntoFy / 3) + 1;
const fyStartYear = qs.getUTCMonth() + 1 >= fyStartMonth ? qs.getUTCFullYear() : qs.getUTCFullYear() - 1;
const fyLabelYear = fyStartMonth === 1 ? fyStartYear : fyStartYear + 1; // FY named by the calendar year it ends in
const quarterId = fyStartMonth === 1 ? `${fyLabelYear}-Q${quarterNumber}` : `FY${fyLabelYear}-Q${quarterNumber}`;
if (asOfMs < qStartMs) throw new Error(`As-of date is before the start of ${quarterId}.`);
const quarterClosed = asOfMs >= qEndMs;
if (quarterClosed) warnings.push(`As-of date is after ${quarterId} ended: this is a final (closed-quarter) report.`);

// ---- Notification destinations ------------------------------------------------
const channels = list('NOTIFY_CHANNELS', 'slack').map((c) => c.toLowerCase()).filter((c) => ['slack', 'teams'].includes(c));
const allowedSuffixes = list('NOTIFY_ALLOWED_HOST_SUFFIXES', 'hooks.slack.com,.logic.azure.com,.powerplatform.com,.powerautomate.com');
function checkUrl(key) {
  const v = readEnv(key);
  if (!v) return { set: false, valid: false, host: null, reason: `${key} is not set` };
  // Strict parse without relying on the URL global (not available in every sandbox).
  const m = v.match(/^(https?):\/\/([a-z0-9.-]+)(?::(\d{1,5}))?(\/[^\s]*)?$/i);
  if (!m || /@/.test(v.split('/').slice(0, 3).join('/'))) return { set: true, valid: false, host: null, reason: `${key} is not a valid URL` };
  const protocol = m[1].toLowerCase();
  const host = m[2].toLowerCase();
  const hostOk = allowedSuffixes.some((s) => (s.startsWith('.') ? host.endsWith(s) : host === s));
  const httpsOk = protocol === 'https' || (protocol === 'http' && /^(127\.0\.0\.1|localhost)$/.test(host) && allowedSuffixes.includes(host));
  if (!httpsOk) return { set: true, valid: false, host, reason: `${key} must use https` };
  if (!hostOk) return { set: true, valid: false, host, reason: `${key} host ${host} is not in NOTIFY_ALLOWED_HOST_SUFFIXES` };
  return { set: true, valid: true, host, reason: null };
}
const dest = { slack: checkUrl('SLACK_WEBHOOK_URL'), teams: checkUrl('TEAMS_WEBHOOK_URL') };

const notifyBlockers = [];
if (sandboxMode) notifyBlockers.push('SANDBOX_MODE=true (synthetic fixture run)');
if (dryRun) notifyBlockers.push('DRY_RUN=true');
if (!notificationsEnabled) notifyBlockers.push('NOTIFICATIONS_ENABLED is not true');
if (!channels.length) notifyBlockers.push('NOTIFY_CHANNELS lists no supported channel (slack, teams)');
for (const c of channels) if (!dest[c].valid) notifyBlockers.push(dest[c].reason);
if (envBlocked) notifyBlockers.push('n8n blocked $env access');

const stampBlockers = [];
if (sandboxMode) stampBlockers.push('SANDBOX_MODE=true');
if (dryRun) stampBlockers.push('DRY_RUN=true');
if (!hubspotMutationsEnabled) stampBlockers.push('HUBSPOT_MUTATIONS_ENABLED is not true');
if (envBlocked) stampBlockers.push('n8n blocked $env access');

// ---- Forecast policy ----------------------------------------------------------
const pacingBasis = str('PACING_BASIS', 'calendar').toLowerCase() === 'business' ? 'business' : 'calendar';
const holidays = [];
for (const h of list('BUSINESS_HOLIDAYS')) { const ms = parseYmd(h); if (ms === null) configErrors.push(`BUSINESS_HOLIDAYS entry "${h}" is not YYYY-MM-DD`); else holidays.push(ms); }
const probabilitySource = str('PROBABILITY_SOURCE', 'hubspot').toLowerCase() === 'stage_map' ? 'stage_map' : 'hubspot';
const stageWeights = {};
for (const pair of list('STAGE_WEIGHTS')) {
  const m = pair.match(/^([A-Za-z0-9_-]{1,64}):(\d+(?:\.\d+)?)$/);
  if (!m || Number(m[2]) > 1) { configErrors.push(`STAGE_WEIGHTS entry "${pair}" must be stageId:0..1`); continue; }
  stageWeights[m[1]] = m[2];
}
if (probabilitySource === 'stage_map' && !Object.keys(stageWeights).length) configErrors.push('PROBABILITY_SOURCE=stage_map requires STAGE_WEIGHTS');
const thresholds = {
  ahead: decIn('PACING_AHEAD_THRESHOLD', '1.10'),
  onTrack: decIn('PACING_ON_TRACK_THRESHOLD', '0.90'),
  atRisk: decIn('PACING_AT_RISK_THRESHOLD', '0.70'),
  criticalProjection: decIn('CRITICAL_PROJECTED_ATTAINMENT', '0.75'),
  minElapsed: decIn('MIN_ELAPSED_FRACTION_FOR_PACING', '0.10', 1),
  minCoverage: decIn('MIN_PIPELINE_COVERAGE', '1.0'),
};
if (!(Number(thresholds.ahead) >= Number(thresholds.onTrack) && Number(thresholds.onTrack) >= Number(thresholds.atRisk))) {
  configErrors.push('Thresholds must satisfy AHEAD >= ON_TRACK >= AT_RISK');
}
const quotaSource = str('QUOTA_SOURCE', 'hubspot_goals').toLowerCase() === 'env' ? 'env' : 'hubspot_goals';
const quotaMap = {};
for (const pair of list('QUOTA_MAP')) {
  const m = pair.match(/^(\d{1,20}):(\d+(?:\.\d+)?)$/);
  if (!m) { configErrors.push(`QUOTA_MAP entry "${pair.slice(0, 40)}" must be ownerId:amount`); continue; }
  quotaMap[m[1]] = m[2];
}
if (quotaSource === 'env' && !sandboxMode && !Object.keys(quotaMap).length) configErrors.push('QUOTA_SOURCE=env requires QUOTA_MAP');
const ownerIdList = (k) => list(k).filter((x) => /^\d{1,20}$/.test(x));

const props = {
  amount: prop('AMOUNT_PROPERTY', 'amount_in_home_currency'),
  hygieneFlag: prop('HYGIENE_FLAG_PROPERTY', 'forecast_hygiene_flag'),
  hygieneCheckedAt: prop('HYGIENE_CHECKED_AT_PROPERTY', 'forecast_hygiene_checked_at'),
};
const config = {
  runId: 'qv-' + new Date(nowMs).toISOString().replace(/[-:.TZ]/g, '').slice(0, 14) + '-' + Math.random().toString(36).slice(2, 8),
  now: new Date(nowMs).toISOString(),
  envBlocked,
  sandboxMode,
  dryRun,
  portalId: sandboxMode ? SYNTHETIC_PORTAL_ID : configuredPortalId,
  trigger: isWebhook ? 'webhook' : 'manual-or-schedule',
  quarter: { id: quarterId, number: quarterNumber, fiscalYear: fyLabelYear, fyStartMonth, startMs: qStartMs, endMs: qEndMs, startIso: new Date(qStartMs).toISOString().slice(0, 10), endIsoExclusive: new Date(qEndMs).toISOString().slice(0, 10), closed: quarterClosed },
  asOf: { ms: asOfMs, iso: new Date(asOfMs).toISOString().slice(0, 10), source: requested.asOf ? 'webhook' : asOfRaw ? 'env' : 'today' },
  currency: { home: str('HOME_CURRENCY', 'USD').toUpperCase() },
  quota: { source: quotaSource, map: quotaMap, goalNameContains: str('GOAL_NAME_CONTAINS', 'quota').toLowerCase() },
  pipeline: {
    probabilitySource,
    stageWeights,
    weightPastDue: safeOff('WEIGHT_PAST_DUE_PIPELINE'),
    pipelines: list('PIPELINES').filter((p) => /^[A-Za-z0-9_-]{1,64}$/.test(p)),
  },
  pacing: { basis: pacingBasis, holidays, thresholds },
  scope: { includeOwnerIds: ownerIdList('INCLUDED_OWNER_IDS'), excludeOwnerIds: ownerIdList('EXCLUDED_OWNER_IDS') },
  guards: { maxInvalidRecordPct: decIn('MAX_INVALID_RECORD_PCT', '10', 100) },
  display: { repLabel: str('REP_LABEL', 'name').toLowerCase() === 'id' ? 'id' : 'name', maxReps: intIn('MAX_REPS_IN_MESSAGE', 25, 1, 40), title: str('REPORT_TITLE', 'Quota vs Actuals: Weekly Pacing').slice(0, 80) },
  hubspot: {
    apiBase: str('HUBSPOT_API_BASE_URL', 'https://api.hubapi.com').replace(/\/+$/, ''),
    appBase: str('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com').replace(/\/+$/, ''),
    props,
    pageSize: intIn('HUBSPOT_SEARCH_PAGE_SIZE', 200, 10, 200),
    maxSearchPages: 50,
    mutationsEnabled: hubspotMutationsEnabled,
    stampAllowed: stampBlockers.length === 0,
    stampBlockers,
  },
  notify: {
    enabled: notificationsEnabled,
    channels,
    destinations: { slack: { set: dest.slack.set, valid: dest.slack.valid, host: dest.slack.host }, teams: { set: dest.teams.set, valid: dest.teams.valid, host: dest.teams.host } },
    allowedByConfig: notifyBlockers.length === 0 && configErrors.length === 0,
    blockers: [...notifyBlockers, ...(configErrors.length ? [`${configErrors.length} configuration error(s)`] : [])],
    forceRepost: safeOff('FORCE_REPOST'),
  },
  configErrors,
  warnings,
};
const safetyDecisions = [
  `Mode: ${sandboxMode ? 'SANDBOX (synthetic fixture, zero network calls)' : 'LIVE (read-only HubSpot searches)'}`,
  `Quarter: ${quarterId} (${config.quarter.startIso} to ${config.quarter.endIsoExclusive}, exclusive) as of ${config.asOf.iso}`,
  `Quota source: ${quotaSource}; probability: ${probabilitySource}; pacing: ${pacingBasis} days`,
  `Notifications: ${config.notify.allowedByConfig ? 'ARMED (' + channels.join(', ') + ')' : 'BLOCKED'}`,
  `HubSpot hygiene stamp: ${config.hubspot.stampAllowed ? 'ARMED' : 'BLOCKED'}`,
];
return [{ json: { config, safetyDecisions } }];

// ============================================================================
// Load Synthetic Quota Fixture  (SANDBOX_MODE=true path - ZERO network calls)
// Embedded object = sample-payloads/quota-variance-fixture.json (verified by
// the simulator).
