  if (failed) throw new Error(`HubSpot ${label} search failed; aborting (no partial forecast): ` + String(failed.error.message || failed.error).slice(0, 300));
  const total = pages.length && typeof pages[0].total === 'number' ? pages[0].total : null;
  if (total !== null && total >= 10000) throw new Error(`HubSpot ${label} search matched ${total} records; the search API cannot page past 10,000. Narrow PIPELINES or the scope.`);
  const last = pages[pages.length - 1] || {};
  if (pages.length >= maxPages && last.paging && last.paging.next) throw new Error(`HubSpot ${label} pagination stopped at ${pages.length} pages with more results pending; aborting.`);
  const seen = new Map();
  for (const p of pages) for (const r of p.results || []) if (r && r.id && !seen.has(String(r.id))) seen.set(String(r.id), r);
  return [...seen.values()];
}
