// ============================================================================
// Variance Calculator  (pure computation, no network)
// Per rep, for the fiscal quarter as of the as-of date:
//   quota (goal_targets summed / prorated, or QUOTA_MAP)  -> Q
//   closed-won ARR in the quarter                         -> W
//   elapsed fraction (calendar or business days)          -> e
//   expected-to-date = Q x e ; pacing variance = W - Q x e ; pacing ratio = W / (Q x e)
//   gap-to-quota = max(0, Q - W)
//   weighted pipeline = sum(amount x probability) of open deals closing in the
//                       rest of the quarter (past-due deals excluded by default)
//   forecast = W + weighted ; projected attainment = forecast / Q
//   coverage = weighted / gap ; required weekly run rate = gap / weeks remaining
// Money is BigInt minor units; ratios are compared as exact fractions.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const input = $input.first().json;
const DAY = 86400000;
const home = config.currency.home;
const T = config.pacing.thresholds;

// ---------------------------------------------------------------- helpers
const ZERO_DP = new Set(['JPY', 'KRW', 'CLP', 'VND', 'ISK', 'UGX', 'XAF', 'XOF', 'PYG', 'RWF']);
const dp = ZERO_DP.has(home) ? 0 : 2;
const pow10 = (n) => 10n ** BigInt(n);
const roundDiv = (num, den) => (num * 2n + den) / (den * 2n); // half-up, num >= 0, den > 0
function parseMoney(raw) {
  if (raw === null || raw === undefined) return { ok: false, empty: true };
  const s = String(raw).trim();
  if (s === '') return { ok: false, empty: true };
  if (!/^(\d+|\d{1,3}(,\d{3})+)(\.\d+)?$/.test(s)) return { ok: false, empty: false };
  const [i, f = ''] = s.replace(/,/g, '').split('.');
  const asInt = BigInt(i + f);
  return { ok: true, minor: f.length <= dp ? asInt * pow10(dp - f.length) : roundDiv(asInt, pow10(f.length - dp)) };
}
function frac(dec) {
  const [i, f = ''] = String(dec).split('.');
  return { num: BigInt(i + f), den: pow10(f.length) };
}
function parseProbability(raw) {
  const s = String(raw ?? '').trim();
  if (!/^\d+(\.\d+)?$/.test(s)) return null;
  const f = frac(s);
  return f.num > f.den ? null : f;
}
function parseInstant(raw) {
  const s = String(raw ?? '').trim();
  if (!s) return null;
  let ms = NaN;
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) ms = Date.parse(s + 'T00:00:00Z');
  else if (/^\d{12,14}$/.test(s)) ms = Number(s);
  else if (/^\d{4}-\d{2}-\d{2}T/.test(s)) ms = Date.parse(s);
  return Number.isFinite(ms) && ms > Date.UTC(1990, 0, 1) && ms < Date.UTC(2100, 0, 1) ? ms : null;
}
const fmt = (minor) => {
  const neg = minor < 0n;
  const m = neg ? -minor : minor;
  const s = m.toString().padStart(dp + 1, '0');
  return (neg ? '-' : '') + (dp ? `${s.slice(0, -dp)}.${s.slice(-dp)}` : s);
};
const pct = (num, den) => (den === 0n ? null : (Number(roundDiv(num * 1000n, den)) / 10).toFixed(1));
const times = (num, den) => (den === 0n ? null : (Number(roundDiv(num * 100n, den)) / 100).toFixed(2));
const geFrac = (n1, d1, f) => n1 * f.den >= f.num * d1; // n1/d1 >= f

// ---------------------------------------------------------------- days
const startDay = Math.floor(config.quarter.startMs / DAY);
const endDay = Math.floor(config.quarter.endMs / DAY);
const asDay = Math.min(Math.floor(config.asOf.ms / DAY), endDay);
const holidaySet = new Set(config.pacing.holidays.map((ms) => Math.floor(ms / DAY)));
const isBusiness = (d) => { const wd = new Date(d * DAY).getUTCDay(); return wd !== 0 && wd !== 6 && !holidaySet.has(d); };
const countDays = (from, to) => {
  if (config.pacing.basis === 'calendar') return Math.max(0, to - from);
  let n = 0;
  for (let d = from; d < to; d++) if (isBusiness(d)) n++;
  return n;
};
const totalDays = countDays(startDay, endDay);
const elapsedDays = countDays(startDay, asDay);
const remainingDays = totalDays - elapsedDays;
const daysPerWeek = config.pacing.basis === 'calendar' ? 7n : 5n;
const eNum = BigInt(elapsedDays);
const eDen = BigInt(Math.max(1, totalDays));
if (totalDays === 0) throw new Error('The quarter has zero pacing days (check BUSINESS_HOLIDAYS / PACING_BASIS).');

// ---------------------------------------------------------------- scope
const inScope = (id) => (!config.scope.includeOwnerIds.length || config.scope.includeOwnerIds.includes(id)) && !config.scope.excludeOwnerIds.includes(id);
const ownerNames = Object.fromEntries((input.owners || []).map((o) => [String(o.id), [o.firstName, o.lastName].filter(Boolean).join(' ').trim()]));
