  sd.snapshots = sd.snapshots || {};
  sd.lastPosted[`${calc.quarter.id}|${calc.asOf.iso}`] = new Date().toISOString();
  sd.snapshots[calc.quarter.id] = calc.snapshot;
  for (const k of Object.keys(sd.lastPosted).sort().slice(0, -60)) delete sd.lastPosted[k];
}
return [{ json: { mode: 'posted', allOk, results } }];

// ============================================================================
// Build Hygiene Stamp Batches  (HUBSPOT_MUTATIONS_ENABLED=true, live, not dry run)
// The ONLY CRM write: flags deals that distort the forecast (past-due close
// date, missing probability, invalid amount, missing owner) on a custom deal
// property. Deals whose flag already has the same value are skipped.
// ============================================================================
const { config } = $('Config & Safety Gate').first().json;
const calc = $('Variance Calculator').first().json;
const P = config.hubspot.props;
const inputs = [];
for (const h of calc.hygiene) {
  const value = [...new Set(h.issues)].sort().join(';');
  if (h.existing === value) continue;
  const properties = { [P.hygieneFlag]: value };
  if (P.hygieneCheckedAt) properties[P.hygieneCheckedAt] = config.now;
  inputs.push({ id: h.dealId, properties });
}
if (!inputs.length) return [{ json: { skip: true, deals: 0 } }];
const out = [];
for (let i = 0; i < inputs.length; i += 100) out.push({ json: { skip: false, url: `${config.hubspot.apiBase}/crm/v3/objects/deals/batch/update`, body: { inputs: inputs.slice(i, i + 100) }, deals: Math.min(100, inputs.length - i) } });
return out;

// ============================================================================
// Hygiene Stamp Result
// ============================================================================
const plan = $('Build Hygiene Stamp Batches').all().map((i) => i.json);
if (plan.length === 1 && plan[0].skip) return [{ json: { attempted: false, stamped: 0, failed: 0, note: 'No hygiene flags to write' } }];
let stamped = 0, failed = 0;
const errors = [];
$input.all().map((i) => i.json).forEach((r, i) => {
  if (r.error) { failed += plan[i] ? plan[i].deals : 0; errors.push(String(r.error.message || r.error).slice(0, 200)); return; }
  stamped += (r.results || []).length;
  for (const e of r.errors || []) { failed++; errors.push(String(e.message || 'error').slice(0, 200)); }
});
return [{ json: { attempted: true, stamped, failed, errors: errors.slice(0, 20) } }];

// ============================================================================
// Forecast Run Report  (terminal)
// ============================================================================
const { config, safetyDecisions } = $('Config & Safety Gate').first().json;
const calc = $('Variance Calculator').first().json;
const nb = $('Notification Builder').first().json;
let notification = null;
try { notification = $('Notification Result').first().json; } catch (e) { notification = null; }
let hygieneStamp = null;
try { hygieneStamp = $('Hygiene Stamp Result').first().json; } catch (e) { hygieneStamp = null; }
const duplicateOnly = !nb.notifyAllowed && nb.notifyBlockers.length > 0 && nb.notifyBlockers.every((b) => /^Already posted/.test(b));
const status = nb.notifyAllowed ? (notification && notification.allOk ? 'POSTED' : 'POST_FAILED') : duplicateOnly ? 'SKIPPED_ALREADY_POSTED' : 'DRY_RUN';
return [{
  json: {
    status,
    quarter: calc.quarter.id,
    asOf: calc.asOf.iso,
    mode: config.sandboxMode ? 'SANDBOX' : config.dryRun ? 'LIVE / DRY-RUN' : 'LIVE',
    pacing: calc.pacing,
    team: { quota: calc.team.quota, won: calc.team.won, attainmentPct: calc.team.attainmentPct, pacingPct: calc.team.pacingPct, forecast: calc.team.forecast, projectedAttainmentPct: calc.team.projectedAttainmentPct, gapToQuota: calc.team.gapToQuota, status: calc.team.status },
    statusCounts: calc.statusCounts,
    reps: calc.reps.map((r) => ({ ownerId: r.ownerId, status: r.status, attainmentPct: r.attainmentPct || null, pacingPct: r.pacingPct || null, flags: r.flags })),
    dataQuality: calc.dataQuality,
    guards: calc.guards,
    notifyBlockedBy: nb.notifyAllowed ? [] : nb.notifyBlockers,
    notification,
    hygieneStamp,
    hygieneStampBlockedBy: hygieneStamp ? [] : config.hubspot.stampBlockers,
    safetyDecisions,
    configWarnings: config.warnings,
    collectionWarnings: calc.collectionWarnings,
  },
}];
